import { useEffect, useState } from "react";
import { API } from "../api/api";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";

export default function SurveyListPage() {
  const [surveys, setSurveys] = useState([]);
  const [loading, setLoading] = useState(true);
  const nav = useNavigate();

  useEffect(() => {
    loadSurveys();
  }, []);

  const loadSurveys = async () => {
    try {
      setLoading(true);
      const res = await API.get("/surveys");
      setSurveys(res.data || []);
    } catch (err) {
      console.log("Survey error:", err);
      setSurveys([]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Navbar />

      <div className="page">
        <div className="container">

          <h2 className="title">🧠 All Surveys</h2>

          {/* ✅ CREATE BUTTON */}
          <button
            className="create-btn"
            onClick={() => nav("/create-survey")}
          >
            + Create Survey
          </button>

          {loading ? (
            <p>Loading surveys...</p>
          ) : surveys.length === 0 ? (
            <p>No surveys found</p>
          ) : (
            surveys.map((s) => (
              <div
                key={s._id}
                className="card"
                onClick={() => nav(`/survey/${s._id}`)}
              >
                <h3>{s.title}</h3>
                <p style={{ opacity: 0.7 }}>
                  Category: {s.category}
                </p>
              </div>
            ))
          )}

          <button className="back-btn" onClick={() => nav("/home")}>
            ← Back Home
          </button>

        </div>
      </div>

      <style>{`
        .page {
          min-height: 100vh;
          background: radial-gradient(circle at top,#1e3a8a,#0b1220 60%);
          color: white;
          padding: 30px;
        }

        .container {
          max-width: 750px;
          margin: auto;
        }

        .title {
          text-align: center;
          margin-bottom: 15px;
        }

        /* ✅ CREATE BUTTON */
        .create-btn {
          width: 25%;
          display: flex;
          justify-content : flex-end;
          text-align:right;
          padding: 12px;
          margin-bottom: 20px;
          border: none;
          background: #22c55e;
          color: white;
          border-radius: 10px;
          cursor: pointer;
          font-size: 16px;
          font-weight: bold;
        }

        .create-btn:hover {
          background: #16a34a;
        }

        .card {
          background: #111827;
          padding: 15px;
          margin: 12px 0;
          border-radius: 12px;
          cursor: pointer;
          transition: 0.2s;
          border: 1px solid transparent;
        }

        .card:hover {
          background: #1f2937;
          transform: scale(1.02);
          border-color: #3b82f6;
        }

        .back-btn {
          margin-top: 20px;
          padding: 10px 15px;
          border: none;
          background: #3b82f6;
          color: white;
          border-radius: 8px;
          cursor: pointer;
        }

        .back-btn:hover {
          background: #2563eb;
        }
      `}</style>
    </>
  );
}
